const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '小球（自静止释放）' },
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' },
      { kind: 'text', payload: 'v 与 g 均竖直向下' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var cx = w * 0.5;
    var ballY = h * 0.30;
    var r = 24;
    var top = 36;
    var bottom = h - 36;

    var guide = visualSdk.polyline([[cx, top + 10], [cx, bottom - 10]]);
    var trail = visualSdk.polyline([[cx, ballY + r + 8], [cx, ballY + r + 58]]);
    var ball = visualSdk.circle(cx, ballY, r);
    var vArrow = visualSdk.arrow(cx + 90, h * 0.38, cx + 90, h * 0.70, { headLength: 14, headWidth: 10 });
    var gArrow = visualSdk.arrow(cx - 90, h * 0.38, cx - 90, h * 0.70, { headLength: 14, headWidth: 10 });

    return {
      schemaVersion: 1,
      sceneId: 'free-fall',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'guide', commands: guide },
        { id: 'trail', commands: trail },
        { id: 'ball', commands: ball },
        { id: 'v-arrow', commands: vArrow },
        { id: 'g-arrow', commands: gArrow }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'guide', stroke: '#9aa9bb', strokeWidth: 1.5, dash: [6, 6] },
          { type: 'path', pathId: 'trail', stroke: '#9aa9bb', strokeWidth: 1.5, dash: [3, 5] },
          { type: 'path', pathId: 'ball', stroke: '#1f2a3a', strokeWidth: 2, fill: '#e8eef8' },
          { type: 'path', pathId: 'v-arrow', stroke: '#1f5fa8', strokeWidth: 3 },
          { type: 'path', pathId: 'g-arrow', stroke: '#b33a2b', strokeWidth: 3 },
          { type: 'label', text: '小球（自静止释放）', x: cx, y: ballY - r - 14, fontSize: 16, fill: '#1f2a3a', textAnchor: 'middle' },
          { type: 'label', text: 'v', x: cx + 102, y: h * 0.56, fontSize: 20, fill: '#1f5fa8', textAnchor: 'start' },
          { type: 'label', text: 'g', x: cx - 102, y: h * 0.56, fontSize: 20, fill: '#b33a2b', textAnchor: 'end' },
          { type: 'label', text: 'v 与 g 均竖直向下', x: cx, y: h - 14, fontSize: 15, fill: '#1f2a3a', textAnchor: 'middle' }
        ]
      }
    };
  }
};
